// Recheck round 2, indexer reconciliation lens: the daily fixes.
//   R2-I1  random lifecycles of index days on both indexes (the demo index, tPend 210 s, and the production one, 6 h),
//          generated by an independent model of AgateIndex's own rules (contracts/src/lib/IndexDays.sol): closeDay
//          only while the previous record is final (C2), with or without a countersign; attest by the record's source
//          (finalAt = max(postedAt + tPend, now) for a NEEDS_SIGN record, unchanged otherwise); the attester's select of
//          the other writer (RecordReplaced, then Attested); veto of the pending record (deleted, the day reopened);
//          carry case 1 (a stale NEEDS_SIGN record dropped, then the day carried at the record before it, or skipped
//          when there is none); carry case 2 (the head day carried, or skipped); time passing and the clock running.
//          Fed through Envio's simulate in batches; after every batch, for every day of the model: the app's label
//          (dayLabel) at the batch's time equals the label the model's record() gives, the value and finalAt equal the
//          record's, and every PENDING row whose finalAt the clock has passed is FINAL.
// Every event is a real ABI encoding (test/ev.ts); no chain, no Docker, no network.
import { createTestIndexer } from "envio";
import { describe, expect, it } from "vitest";
import { CLOCK_EVERY } from "../../../src/lib/clock.ts";
import { dayLabel } from "../../../src/lib/labels.ts";
import { ev } from "../../ev.ts";
import { DEMO, DOLLAR, H100, H200, REAL, START, U, user } from "../../world.ts";

type TI = ReturnType<typeof createTestIndexer>;
const run = (indexer: TI, simulate: unknown[]) => indexer.process({ chains: { 10143: { simulate: simulate as never } } });

function prng(seed: number) {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4_294_967_296;
  };
}

interface Rec {
  value: number;
  carried: boolean;
  source: string;
  digest: string;
  needsSign: boolean;
  postedAt: number;
  finalAt: number; // 0: not known (NEEDS_SIGN, not attested)
  attested: boolean;
}

/** One GPU on one index, as IndexDays keeps it. */
class Model {
  head: number;
  recs = new Map<number, Rec>();
  vetoed = new Set<number>();
  dropped = new Set<number>();
  skipped = new Set<number>();
  touched = new Set<number>();
  constructor(
    readonly index: string,
    readonly gpu: string,
    readonly tPend: number,
    readonly firstDay: number,
  ) {
    this.head = firstDay;
  }
  pending(): Rec | null {
    const r = this.recs.get(this.head - 1);
    if (!r || r.carried) return null;
    return r.finalAt !== 0 && now >= r.finalAt ? null : r;
  }
  label(d: number, t: number): string {
    const r = this.recs.get(d);
    if (r) {
      if (r.carried) return this.dropped.has(d) || this.vetoed.has(d) ? "carried, unverified" : "carried";
      return r.finalAt !== 0 && t >= r.finalAt ? "final" : "pending";
    }
    if (this.skipped.has(d)) return "skipped";
    if (this.vetoed.has(d) || this.dropped.has(d)) return "pending"; // reopened, waiting to be closed again
    return "open";
  }
}

let now = 0;
let blk = START + 10;
let logIx = 0;
const dig = (n: number) => `0x${n.toString(16).padStart(64, "0")}`;

describe("R2-I1: DailyFix equals an independent model of AgateIndex's records", () => {
  for (const seed of [3, 14, 59]) {
    it(`seed ${seed}: 2 indexes, about 400 index events in 10 batches, the clock between them`, async () => {
      const rnd = prng(seed);
      const i = createTestIndexer();
      now = 1_791_000_000;
      blk = START + 10;
      let rangeStart = START;
      const models = [new Model(DEMO.index, H100, 210, 20_727), new Model(REAL.index, H200, 21_600, 20_727)];
      let n = 0;
      let selects = 0;
      let vetoes = 0;
      let drops = 0;
      let skips = 0;
      let finals = 0;
      for (let batch = 0; batch < 10; batch++) {
        const items: unknown[] = [];
        const at = (m: Model, name: string, args: Record<string, unknown>) => {
          items.push(ev("AgateIndex", name, args, { src: m.index, block: blk, ts: now, logIndex: logIx++ }));
          m.touched.add(Number(args.day));
          n++;
        };
        for (let step = 0; step < 40; step++) {
          blk++;
          logIx = 0;
          now += 1 + Math.floor(rnd() * (rnd() < 0.2 ? 30_000 : 200));
          const m = models[rnd() < 0.5 ? 0 : 1]!;
          const p = m.pending();
          const a = rnd();
          if (p === null && a < 0.45) {
            // closeDay(head): the previous record is final (C2)
            const d = m.head;
            const needsSign = rnd() < 0.4;
            const value = 1_500_000 + Math.floor(rnd() * 3_000_000);
            const digest = dig(blk * 10 + 1);
            at(m, "DayClosed", { gpuId: m.gpu, day: d, source: user(1), value, status: 1, fresh: 5, held: 0, freshMedian: value, changed: needsSign, needsSign, late: false, incomplete: false, digest });
            m.recs.set(d, { value, carried: false, source: user(1), digest, needsSign, postedAt: now, finalAt: needsSign ? 0 : now + m.tPend, attested: false });
            m.head = d + 1;
          } else if (p !== null && !p.attested && a < 0.6) {
            const d = m.head - 1;
            const fin = Math.max(p.postedAt + m.tPend, now);
            if (rnd() < 0.6) {
              // attest by the record's source: finalAt set for a NEEDS_SIGN record, unchanged otherwise
              if (p.needsSign) p.finalAt = fin;
              p.attested = true;
              at(m, "Attested", { gpuId: m.gpu, day: d, by: user(8), source: p.source, digest: p.digest, finalAt: BigInt(p.finalAt) });
            } else {
              // the attester's select of the other writer: RecordReplaced, then Attested, final at max(postedAt + tPend, now)
              const value = 1_500_000 + Math.floor(rnd() * 3_000_000);
              const digest = dig(blk * 10 + 2);
              at(m, "RecordReplaced", { gpuId: m.gpu, day: d, by: user(8), oldSource: p.source, newSource: user(2), oldValue: p.value, newValue: value, oldDigest: p.digest, newDigest: digest });
              at(m, "Attested", { gpuId: m.gpu, day: d, by: user(8), source: user(2), digest, finalAt: BigInt(fin) });
              Object.assign(p, { value, source: user(2), digest, finalAt: fin, attested: true });
              selects++;
            }
          } else if (p !== null && a < 0.72) {
            // veto of the pending record: deleted, the day reopened
            const d = m.head - 1;
            at(m, "Vetoed", { gpuId: m.gpu, day: d, by: user(9), source: p.source, digest: p.digest, value: p.value });
            m.recs.delete(d);
            m.vetoed.add(d);
            m.head = d;
            vetoes++;
          } else if (p !== null && p.needsSign && !p.attested && a < 0.85) {
            // carry case 1: the stale NEEDS_SIGN record dropped, the day carried at the record before it (or skipped)
            const d = m.head - 1;
            at(m, "FixDropped", { gpuId: m.gpu, day: d, source: p.source, value: p.value, digest: p.digest });
            m.recs.delete(d);
            m.dropped.add(d);
            const before = m.recs.get(d - 1);
            if (before) {
              at(m, "DayCarried", { gpuId: m.gpu, day: d, value: before.value, carryCase: 1, dropped: true, missAdvanced: 0 });
              m.recs.set(d, { value: before.value, carried: true, source: "", digest: "", needsSign: false, postedAt: now, finalAt: now, attested: false });
            } else {
              at(m, "DaySkipped", { gpuId: m.gpu, day: d, carryCase: 1 });
              m.skipped.add(d);
            }
            m.head = d + 1;
            drops++;
          } else if (p === null && a < 0.6) {
            // carry case 2: the head day without quorum, carried at the record before it (or skipped)
            const d = m.head;
            const before = m.recs.get(d - 1);
            if (before) {
              at(m, "DayCarried", { gpuId: m.gpu, day: d, value: before.value, carryCase: 2, dropped: false, missAdvanced: 1 });
              m.recs.set(d, { value: before.value, carried: true, source: "", digest: "", needsSign: false, postedAt: now, finalAt: now, attested: false });
            } else {
              at(m, "DaySkipped", { gpuId: m.gpu, day: d, carryCase: 2 });
              m.skipped.add(d);
              skips++;
            }
            m.head = d + 1;
          }
        }
        // the clock: a filler event just before a clock block carries the batch's time to it, and one just after it makes
        // simulate run that block in this batch (it runs block handlers up to the batch's last event). simulate aligns
        // `_every` from the start of each process() range (the config's start block, then the block after the previous
        // range's last event), not from the config's start block as a running indexer does (envio index.d.ts)
        const nextClock = rangeStart + Math.ceil((blk + 2 - rangeStart) / CLOCK_EVERY) * CLOCK_EVERY;
        const drip = (b: number) => ev("AgateDollar", "Dripped", { to: user(3), amount: 1n * U, nextAt: BigInt(now + 86_400) }, { src: DOLLAR, block: b, ts: now, logIndex: 0 });
        items.push(drip(nextClock - 1), drip(nextClock + 1));
        rangeStart = nextClock + 2;
        blk = rangeStart;
        await run(i, items);
        // ---- reconcile every day the model knows
        for (const m of models) {
          for (const d of m.touched) {
            const id = `${m.index}-${m.gpu}-${d}`;
            const f = await i.DailyFix.get(id);
            const want = m.label(d, now);
            expect(dayLabel(f ?? null, BigInt(now)), `${id} after batch ${batch}`).toBe(want);
            const r = m.recs.get(d);
            if (r) {
              expect(f!.value, `${id} value`).toBe(BigInt(r.value));
              expect(f!.finalAt, `${id} finalAt`).toBe(r.finalAt === 0 ? undefined : BigInt(r.finalAt));
              // the clock ran at the batch's time: a record final by then is no longer PENDING
              if (!r.carried && r.finalAt !== 0 && now >= r.finalAt) {
                expect(f!.state, `${id} state after the clock`).toBe("FINAL");
                finals++;
              }
            }
          }
        }
      }
      // not degenerate: every kind of transition happened
      expect(n).toBeGreaterThan(150);
      expect(selects).toBeGreaterThan(0);
      expect(vetoes).toBeGreaterThan(0);
      expect(drops).toBeGreaterThan(0);
      expect(finals).toBeGreaterThan(20);
      void skips;
    }, 120_000);
  }
});
